In case anyone finds it helpful, here's a highlighter for vim's builtin named colors (found in $VIMRUNTIME/rgb.txt):
```lua
local hipatterns = require'mini.hipatterns'
local color_map = vim.api.nvim_get_color_map()
hipatterns.setup({
    highlighters = {
        named_color = {
            pattern = '%w+',
            group = function(_, match)
                local color = color_map[match]
                if color == nil then return nil end
                local hex = require'bit'.tohex(color, 6)
                return hipatterns.compute_hex_color_group('#' .. hex, 'bg')
            end
        },
    },
})
```
